// Optimized photos live in public/images as name.webp plus a smaller name-800.webp (name-400.webp for portraits),
// generated by `npm --prefix frontend run images`. This gives <img> both sizes so phones download the small one.
const portraits = new Set(["principal", "secretary"]);

export function responsiveImage(src) {
  const match = /^\/images\/(.+)\.webp$/.exec(src || "");
  if (!match) return { src };
  const [small, large] = portraits.has(match[1]) ? [400, 800] : [800, 1600];
  return { src, srcSet: `/images/${match[1]}-${small}.webp ${small}w, ${src} ${large}w` };
}
